import java.io.*;import java.nio.file.*;public class Main{static String[] parse(String s){String[]f=s.split("\\|",-1);if(f.length!=7)throw new IllegalArgumentException("wrong field count");Integer.parseInt(f[3]);Double.parseDouble(f[6]);return f;}static String find(Path p,String id)throws IOException{try(BufferedReader r=Files.newBufferedReader(p)){String s;while((s=r.readLine())!=null)try{String[]f=parse(s);if(f[0].equals(id))return String.join("|",f);}catch(RuntimeException e){System.err.println("Damaged line skipped: "+s);}}return null;}public static void main(String[]a)throws Exception{Path p=Path.of("passes.txt");if(a.length>1&&a[0].equals("find"))System.out.println(find(p,a[1]));else System.out.println("Usage: java Main find <passId>; add/list operations are described in TASK_REPORT.md");}}